const agentOutput = $input.first().json;
const outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

const PRICE_PATTERN = /\$\s?\d{1,3}(\.\d{3})+(,\d+)?|\bUSD\s?\d[\d.,]*|\b\d{1,3}(\.\d{3}){2,}\b|\b\d+\s?(mil|millones)\s?(de\s?)?(pesos|ars|usd|d[oó]lares)?\b/i;

// Ignorar los tags de media (las URLs de Cloudinary traen números largos que no son precios)
const textToCheck = outputText.replace(/【[^】]*】/g, '');
const mentionsPrice = PRICE_PATTERN.test(textToCheck);

const priceStep = steps.find(s =>
  ['get_modelos', 'get_precios'].some(t => s.action?.tool?.toLowerCase().startsWith(t))
);
const priceToolCalled = !!priceStep;

if (mentionsPrice && !priceToolCalled) {
  return [{
    json: {
      action: 'force_recovery',
      reason: 'precio_sin_tool',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

return [{
  json: {
    action: 'passthrough',
    output: outputText,
    intermediateSteps: steps
  }
}];

